#include "fixture_qualification_controller.m"
#include <assert.h>
static int response(AxFixtureCase c,unsigned status,const char*json){unsigned char frame[2048];size_t n=strlen(json);frame[0]=status>>24;frame[1]=status>>16;frame[2]=status>>8;frame[3]=status;frame[4]=n>>24;frame[5]=n>>16;frame[6]=n>>8;frame[7]=n;memcpy(frame+8,json,n);return accepted(c,frame,n+8);}
